// Dump harness for internal/width: dumps the tables of unicode-width 0.2.2 and generates
// strings with the widths of the *real* crate, for the differential tests.
//
// Build it offline in a scratch crate (never inside the repository):
//
//   mkdir -p $W/src && cd $W
//   printf '[package]\nname="wdump"\nversion="0.1.0"\nedition="2021"\n[dependencies]\nunicode-width="=0.2.2"\n' > Cargo.toml
//   cp ~/.cargo/registry/src/*/unicode-width-0.2.2/src/tables.rs src/tables.rs
//   cat <repo>/internal/width/testdata/dump/tables_patch.rs >> src/tables.rs   # exposes private fns
//   cp <repo>/internal/width/testdata/dump/main.rs src/main.rs
//   cargo --offline build --release
//
// Modes (the binary is target/release/wdump):
//   wdump dump <outdir>               write the testdata/*.txt table dumps (go generate input)
//   wdump fuzz <count> <seed>         stdout: "<width>\t<hex(utf-8)>" per random string
//   wdump golden <count> <seed>       stdout: golden strings in the same format
//   wdump matrix                      stdout: bounded-exhaustive strings over small alphabets
//   wdump emoji <emoji-test.txt>      stdout: the fully-qualified and component emoji of the
//                                     unicode-width test data, same format
#![allow(dead_code)]
mod tables;

use std::collections::HashSet;
use std::fmt::Write as _;
use std::io::Write as _;
use unicode_width::{UnicodeWidthChar, UnicodeWidthStr};

const HEADER: &str = "# unicode-width 0.2.2 (Unicode 17.0.0), generated by testdata/dump/main.rs; do not edit.\n";

fn ranges<F: Fn(u32) -> String>(f: F) -> String {
    // Collapses runs of equal strings into "START END value" lines (hex bounds).
    let mut out = String::from(HEADER);
    let mut start = 0u32;
    let mut cur = f(0);
    for cp in 1..=0x10FFFFu32 {
        let v = f(cp);
        if v != cur {
            writeln!(out, "{start:X} {:X}{cur}", cp - 1).unwrap();
            start = cp;
            cur = v;
        }
    }
    writeln!(out, "{start:X} 10FFFF{cur}").unwrap();
    out
}

fn bool_ranges<F: Fn(char) -> bool>(f: F) -> String {
    // Only the ranges where f is true; surrogates are false.
    let mut out = String::from(HEADER);
    let mut start: Option<u32> = None;
    for cp in 0..=0x110000u32 {
        let v = cp <= 0x10FFFF && char::from_u32(cp).map_or(false, &f);
        match (start, v) {
            (None, true) => start = Some(cp),
            (Some(s), false) => {
                writeln!(out, "{s:X} {:X}", cp - 1).unwrap();
                start = None;
            }
            _ => {}
        }
    }
    out
}

fn dump(dir: &str) {
    std::fs::create_dir_all(dir).unwrap();
    let w = |name: &str, s: String| std::fs::write(format!("{dir}/{name}"), s).unwrap();

    // lookup.txt: START END RAW WIDTH INFO(hex); surrogates use the raw trie entry directly.
    w(
        "lookup.txt",
        ranges(|cp| match char::from_u32(cp) {
            Some(c) => {
                let (width, info) = tables::dbg_lookup(c);
                format!(" {} {} {:04X}", tables::dbg_raw(cp), width, info)
            }
            None => {
                let raw = tables::dbg_raw(cp);
                assert!(raw < 3, "surrogate with special raw width");
                format!(" {raw} {raw} 0000")
            }
        })
        .replacen("\n", "\n# columns: start end raw width info\n", 1),
    );
    // char_widths.txt: char::width() of the real crate; -1 = None, -2 = surrogate.
    w(
        "char_widths.txt",
        ranges(|cp| match char::from_u32(cp) {
            Some(c) => format!(" {}", c.width().map_or(-1, |w| w as i32)),
            None => " -2".to_string(),
        })
        .replacen("\n", "\n# columns: start end width (-1 = None, -2 = surrogate)\n", 1),
    );
    // The static table behind is_transparent_zero_width.
    let mut s = String::from(HEADER);
    for (lo, hi) in tables::dbg_non_transparent_zero_widths() {
        writeln!(s, "{lo:X} {hi:X}").unwrap();
    }
    w("non_transparent_zero_widths.txt", s);
    w("transparent_zero_width.txt", bool_ranges(tables::dbg_transparent_zero_width));
    w("ligature_transparent.txt", bool_ranges(tables::dbg_ligature_transparent));
    w("emoji_presentation_seq.txt", bool_ranges(tables::starts_emoji_presentation_seq));
    w(
        "text_presentation_seq.txt",
        bool_ranges(tables::starts_non_ideographic_text_presentation_seq),
    );
    w("emoji_modifier_base.txt", bool_ranges(tables::is_emoji_modifier_base));

    // The patched copy must agree with the real crate.
    let mut bad = 0;
    for cp in 0..=0x10FFFFu32 {
        if let Some(c) = char::from_u32(cp) {
            if tables::single_char_width(c) != c.width() {
                bad += 1;
            }
        }
    }
    eprintln!("patched-copy vs real crate char mismatches: {bad}");
}

// ---------------------------------------------------------------------------------------------
// Random strings

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        // splitmix64
        self.0 = self.0.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

fn push_range(v: &mut Vec<char>, lo: u32, hi: u32) {
    for cp in lo..=hi {
        if let Some(c) = char::from_u32(cp) {
            v.push(c);
        }
    }
}

fn singles() -> Vec<char> {
    let mut v: Vec<char> = Vec::new();
    // ASCII, CJK, controls
    for c in "abcxyz XYZ 019#*-_.,'\"".chars() {
        v.push(c);
    }
    for c in "\r\n\r\n\t\u{0}\u{1}\u{1F}\u{7F}\u{80}\u{85}\u{9F}\u{A0}\u{A1}\u{AD}".chars() {
        v.push(c);
    }
    for c in "世界漢字한国Ａｂ（）、。ー".chars() {
        v.push(c);
    }
    // Combining marks and default ignorables
    for cp in [
        0x300u32, 0x301, 0x308, 0x338, 0x345, 0x34F, 0x483, 0x591, 0x5B0, 0x610, 0x64B, 0x651, 0x65F,
        0x670, 0x6D6, 0x6E1, 0x900, 0x93C, 0x9BE, 0x9D7, 0xB3E, 0x1160, 0x11A8, 0x17B4, 0x17B5,
        0x17B7, 0x180B, 0x180C, 0x180D, 0x180F, 0x200B, 0x200C, 0x200E, 0x2060, 0x20D0, 0x20E3,
        0x3099, 0xA8FA, 0xFE00, 0xFE01, 0xFE02, 0xFE03, 0xFE0E, 0xFE0F, 0xFEFF, 0xE0001, 0xE0100,
        0xE01EF,
    ] {
        v.push(char::from_u32(cp).unwrap());
    }
    v.push('\u{200D}');
    v.push('\u{200D}');
    v.push('\u{200D}'); // ZWJ is weighted
    v.push('\u{FE0F}');
    v.push('\u{FE0E}');
    v.push('\u{FE01}');
    // Prepended concatenation marks and other special widths
    for cp in [0x600u32, 0x601, 0x605, 0x6DD, 0x70F, 0x890, 0x891, 0x8E2, 0x115F, 0x17A4, 0x17D8, 0x2D7F] {
        v.push(char::from_u32(cp).unwrap());
    }
    // Quotes with VS1
    for c in "\u{2018}\u{2019}\u{201C}\u{201D}\u{2014}\u{2026}".chars() {
        v.push(c);
    }
    // Ambiguous
    for c in "¡°±²αβЖ┌".chars() {
        v.push(c);
    }
    // Regional indicators
    push_range(&mut v, 0x1F1E6, 0x1F1FF);
    push_range(&mut v, 0x1F1E6, 0x1F1E9);
    // Emoji
    for cp in [
        0x1F600u32, 0x1F468, 0x1F469, 0x1F467, 0x1F466, 0x2764, 0x263A, 0x270C, 0x2600, 0x231A,
        0x23E9, 0x2B50, 0x1F3F4, 0x1F525, 0x1F44D, 0x1F9D1, 0x1F201, 0x1F170, 0x1F004, 0x1F3C3,
        0x1F46A, 0x1F52A, 0x1FAF1, 0x1F91D, 0x2640, 0x2642, 0x2695, 0x26A7, 0x1F308, 0x2B1B,
        0x1F9B0, 0x1F3FB, 0x1F3FC, 0x1F3FD, 0x1F3FE, 0x1F3FF, 0x00A9, 0x00AE, 0x203C, 0x2122,
        0x2139, 0x21A9, 0x2328, 0x23CF, 0x24C2, 0x25AA, 0x2660, 0x2934, 0x3030, 0x303D, 0x3297,
    ] {
        v.push(char::from_u32(cp).unwrap());
    }
    // Digits, # and * as keycap bases are in the ASCII set above; keycap
    // Tag characters
    push_range(&mut v, 0xE0061, 0xE007A);
    push_range(&mut v, 0xE0030, 0xE0039);
    v.push('\u{E007F}');
    v.push('\u{E007F}');
    v.push('\u{E0020}');
    // Arabic
    for cp in [0x644u32, 0x6B5, 0x6B6, 0x6B7, 0x6B8, 0x76A, 0x8A6, 0x8C7, 0x628, 0x627, 0x633, 0x67E, 0x649] {
        v.push(char::from_u32(cp).unwrap());
    }
    push_range(&mut v, 0x622, 0x627);
    push_range(&mut v, 0x871, 0x882);
    // Hebrew
    for cp in [0x5D0u32, 0x5DC, 0x5D1, 0x5D2] {
        v.push(char::from_u32(cp).unwrap());
    }
    // Khmer
    push_range(&mut v, 0x1780, 0x17AF);
    for cp in [0x17D2u32, 0x17D2, 0x17D2, 0x17B6, 0x17C9, 0x17D3, 0x17DD] {
        v.push(char::from_u32(cp).unwrap());
    }
    // Buginese
    for cp in [0x1A10u32, 0x1A15, 0x1A17, 0x1A18, 0x1A11] {
        v.push(char::from_u32(cp).unwrap());
    }
    // Tifinagh
    push_range(&mut v, 0x2D31, 0x2D3A);
    push_range(&mut v, 0x2D60, 0x2D6F);
    v.push('\u{2D7F}');
    v.push('\u{2D7F}');
    // Lisu
    push_range(&mut v, 0xA4F6, 0xA4FF);
    // Old Turkic
    for cp in [0x10C03u32, 0x10C32, 0x10C00, 0x10C33] {
        v.push(char::from_u32(cp).unwrap());
    }
    // Kirat Rai
    push_range(&mut v, 0x16D60, 0x16D6B);
    // Both sides of every range and constant that width_in_str tests against.
    for (lo, hi) in [
        (0x6B5u32, 0x6B8u32),
        (0x622, 0x882),
        (0x1780, 0x17AF),
        (0x2D31, 0x2D65),
        (0x2D6F, 0x2D6F),
        (0xA4F8, 0xA4FB),
        (0xA4FC, 0xA4FD),
        (0x1F1E6, 0x1F1FF),
        (0x1F3FB, 0x1F3FF),
        (0x30, 0x39),
        (0xE0061, 0xE007A),
        (0xE0030, 0xE0039),
        (0xFE00, 0xFE0F),
        (0x180B, 0x180F),
        (0x17B4, 0x17B5),
        (0xE0100, 0xE01EF),
        (0x644, 0x644),
        (0x76A, 0x76A),
        (0x8A6, 0x8A6),
        (0x8C7, 0x8C7),
        (0x5D0, 0x5D0),
        (0x5DC, 0x5DC),
        (0x17D2, 0x17D2),
        (0x1A10, 0x1A10),
        (0x1A15, 0x1A15),
        (0x1A17, 0x1A17),
        (0x2D7F, 0x2D7F),
        (0x10C03, 0x10C03),
        (0x10C32, 0x10C32),
        (0x20E3, 0x20E3),
        (0x1F3F4, 0x1F3F4),
        (0xE007F, 0xE007F),
        (0x16D63, 0x16D63),
        (0x16D67, 0x16D69),
        (0x34F, 0x34F),
        (0x2018, 0x2019),
        (0x201C, 0x201D),
        (0x23, 0x23),
        (0x2A, 0x2A),
        (0xA0, 0xA0),
        (0xA, 0xA),
        (0xD, 0xD),
        (0x200D, 0x200D),
    ] {
        for cp in [lo - 1, lo, hi, hi + 1] {
            if let Some(c) = char::from_u32(cp) {
                v.push(c);
            }
        }
    }
    v
}

/// Sequences built from random parts, so that ligature states are entered at many lengths.
fn dynamic_atom(rng: &mut Rng) -> String {
    let pick = |rng: &mut Rng, xs: &[u32]| char::from_u32(xs[rng.below(xs.len())]).unwrap();
    let mut s = String::new();
    let endings: [&str; 6] = ["", "", "\u{200D}\u{1F600}", "\u{200D}\u{24C2}\u{FE0F}", "\u{200D}", "a"];
    match rng.below(9) {
        0 => {
            // Tag sequence: base, k tag letters/digits, tag end, optional ZWJ continuation.
            s.push_str(["\u{1F3F4}", "\u{1F600}", "a", ""][rng.below(4)]);
            for _ in 0..rng.below(13) {
                let cp = match rng.below(12) {
                    0..=1 => 0xE0030 + rng.below(10),
                    2 => [0xE0030, 0xE0039][rng.below(2)],
                    // just outside the digit and letter ranges, and the tag end itself
                    4..=5 => [0xE002F, 0xE003A, 0xE0060, 0xE007B, 0xE007F, 0xE0020][rng.below(6)],
                    6..=7 => [0xE0061, 0xE007A][rng.below(2)],
                    _ => 0xE0061 + rng.below(26),
                };
                s.push(char::from_u32(cp as u32).unwrap());
            }
            if rng.below(8) != 0 {
                s.push('\u{E007F}');
            }
            s.push_str(endings[rng.below(endings.len())]);
        }
        1 => {
            // Regional indicator chains with ZWJs in random places.
            for _ in 0..1 + rng.below(8) {
                if rng.below(4) == 0 {
                    s.push('\u{200D}');
                }
                if rng.below(10) == 0 {
                    s.push('\u{1F1E5}');
                } else {
                    s.push(char::from_u32(0x1F1E6 + rng.below(26) as u32).unwrap());
                }
            }
            s.push_str(endings[rng.below(endings.len())]);
        }
        2 => {
            // Keycap forms.
            s.push(pick(rng, &[0x23, 0x2A, 0x30, 0x35, 0x39, 0x61]));
            for _ in 0..rng.below(3) {
                s.push(pick(rng, &[0xFE0F, 0x20E3, 0x200D, 0xFE0E]));
            }
            s.push_str(endings[rng.below(endings.len())]);
        }
        3 => {
            // Emoji modifier and ZWJ chains.
            for _ in 0..1 + rng.below(4) {
                s.push(pick(rng, &[0x1F44D, 0x1F9D1, 0x1F600, 0x2764, 0x270C, 0x24C2, 0x61, 0x1F3FB, 0x1F3FA, 0x1F400]));
                for _ in 0..rng.below(3) {
                    s.push(pick(rng, &[0x1F3FB, 0x1F3FD, 0x1F3FF, 0x1F3FA, 0x1F400, 0xFE0F, 0x200D, 0xFE0E, 0x34F]));
                }
                if rng.below(2) == 0 {
                    s.push('\u{200D}');
                }
            }
        }
        4 => {
            // Arabic Lam ... Alef with transparent marks in between.
            s.push(pick(rng, &[0x644, 0x6B5, 0x6B6, 0x6B8, 0x76A, 0x8A6, 0x8C7, 0x628, 0x5D0]));
            for _ in 0..rng.below(4) {
                s.push(pick(rng, &[0x64B, 0x65F, 0x670, 0xFE0F, 0xFE0E, 0x200D, 0x34F, 0x605, 0x6D6, 0x1E94B, 0x17B5, 0x301, 0xFE01]));
            }
            s.push(pick(rng, &[0x622, 0x623, 0x627, 0x625, 0x8A1, 0x882, 0x871, 0x61, 0x644]));
        }
        5 => {
            // Khmer coeng and eligible letters.
            for _ in 0..1 + rng.below(3) {
                s.push(pick(rng, &[0x1780, 0x1783, 0x17A0, 0x17AF, 0x17B0, 0x1781, 0x61]));
                for _ in 0..rng.below(3) {
                    s.push(pick(rng, &[0x17D2, 0x200D, 0xFE0F, 0x17B4, 0x17D2]));
                }
            }
        }
        6 => {
            // Tifinagh, Buginese, Hebrew, Old Turkic, Lisu, Kirat Rai joiners.
            let sets: [&[u32]; 6] = [
                &[0x2D4F, 0x2D3E, 0x2D7F, 0x200D, 0xFE0F, 0x2D66, 0x2D6F, 0x301],
                &[0x1A15, 0x1A17, 0x1A10, 0x200D, 0xFE0E, 0x338, 0x1A18],
                &[0x5D0, 0x5DC, 0x200D, 0xFE0F, 0x5B0, 0x5D1],
                &[0x10C32, 0x10C03, 0x200D, 0xFE0F, 0x301],
                &[0xA4F8, 0xA4FB, 0xA4FC, 0xA4FD, 0xA4F7, 0xA4FE, 0xFE0F, 0x200D, 0x301],
                &[0x16D63, 0x16D67, 0x16D68, 0x16D69, 0x16D6A, 0x16D62, 0x200D],
            ];
            let set = sets[rng.below(sets.len())];
            for _ in 0..1 + rng.below(6) {
                s.push(pick(rng, set));
            }
        }
        7 => {
            // Variation selectors after quotes / text-presentation bases.
            s.push(pick(rng, &[0x2018, 0x2019, 0x201C, 0x201D, 0x231A, 0x2648, 0x1F201, 0x1F600, 0x23, 0x61, 0x2764]));
            for _ in 0..rng.below(4) {
                s.push(pick(rng, &[0xFE00, 0xFE01, 0xFE02, 0xFE0E, 0xFE0F, 0x200D, 0x34F, 0x301]));
            }
        }
        _ => {
            // CR / LF with decorations.
            for _ in 0..1 + rng.below(5) {
                s.push(pick(rng, &[0x0D, 0x0A, 0x0D, 0x0A, 0xFE0F, 0x200D, 0x61, 0x09, 0x85, 0xA0]));
            }
        }
    }
    s
}

