fn interesting_cp(rng: &mut Rng) -> char {
    loop {
        let cp = match rng.below(10) {
            0 => rng.below(0x300) as u32,
            1 => 0x300 + rng.below(0x1000) as u32,
            2 => 0x1000 + rng.below(0x2000) as u32,
            3 => 0x2000 + rng.below(0x1000) as u32,
            4 => 0x3000 + rng.below(0x1000) as u32,
            5 => 0xA000 + rng.below(0x1000) as u32,
            6 => 0xF900 + rng.below(0x700) as u32,
            7 => 0x1F000 + rng.below(0x1000) as u32,
            8 => 0x10000 + rng.below(0x8000) as u32,
            _ => 0xE0000 + rng.below(0x200) as u32,
        };
        if let Some(c) = char::from_u32(cp) {
            return c;
        }
    }
}

fn gen_string(rng: &mut Rng, singles: &[char], atoms: &[String]) -> String {
    let len = 1 + rng.below(12);
    let mut s = String::new();
    match rng.below(10) {
        0..=3 => {
            // plain pool draws
            for _ in 0..len {
                s.push(singles[rng.below(singles.len())]);
            }
        }
        4..=8 => {
            // atoms mixed with pool draws, ASCII padding sometimes
            for _ in 0..len {
                match rng.below(12) {
                    0..=3 => s.push_str(&atoms[rng.below(atoms.len())]),
                    4..=6 => s.push_str(&dynamic_atom(rng)),
                    7..=10 => s.push(singles[rng.below(singles.len())]),
                    _ => s.push(interesting_cp(rng)),
                }
            }
        }
        _ => {
            // fully random scalars from interesting blocks
            for _ in 0..len {
                s.push(interesting_cp(rng));
            }
        }
    }
    s
}

fn hex(s: &str) -> String {
    let mut out = String::with_capacity(s.len() * 2);
    for b in s.bytes() {
        write!(out, "{b:02x}").unwrap();
    }
    out
}

fn fuzz(count: usize, seed: u64) {
    let singles = singles();
    let atoms = atoms();
    let mut rng = Rng(seed);
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    for _ in 0..count {
        let s = gen_string(&mut rng, &singles, &atoms);
        // Real-crate width; the patched copy must agree too.
        let w = s.width();
        assert_eq!(w, tables::str_width(&s), "patched copy disagrees: {s:?}");
        writeln!(out, "{w}\t{}", hex(&s)).unwrap();
    }
}

// ---------------------------------------------------------------------------------------------
// Golden selection: keep the strings that exercise new (state, input, add, next-state) transitions.

fn bucket(c: char) -> u64 {
    let cp = c as u32;
    // Characters named in width_in_str's match arms stay distinct; ranges collapse to
    // first / middle / last.
    const EXACT: &[u32] = &[
        0x0A, 0x0D, 0x20, 0x61, 0xA0, 0xFE0F, 0xFE01, 0xFE0E, 0x2018, 0x2019, 0x201C, 0x201D,
        0x200D, 0x644, 0x76A, 0x8A6, 0x8C7, 0x5D0, 0x5DC, 0x17D2, 0x1A10, 0x1A15, 0x1A17, 0x2D7F,
        0x10C03, 0x10C32, 0x20E3, 0x1F3F4, 0xE007F, 0x16D63, 0x16D67, 0x16D68, 0x16D69, 0x34F,
        0x1F600, 0x2764,
    ];
    const RANGES: &[(u32, u32)] = &[
        (0x6B5, 0x6B8),
        (0x622, 0x882),
        (0x1780, 0x17AF),
        (0x2D31, 0x2D65),
        (0x2D6F, 0x2D6F),
        (0xA4F8, 0xA4FB),
        (0xA4FC, 0xA4FD),
        (0x1F1E6, 0x1F1FF),
        (0x1F3FB, 0x1F3FF),
        (0x30, 0x39),
        (0x23, 0x23),
        (0x2A, 0x2A),
        (0xE0061, 0xE007A),
        (0xE0030, 0xE0039),
        (0xFE00, 0xFE0F),
        (0x180B, 0x180F),
        (0x17B4, 0x17B5),
        (0xE0100, 0xE01EF),
    ];
    if EXACT.contains(&cp) {
        return cp as u64;
    }
    for (i, &(lo, hi)) in RANGES.iter().enumerate() {
        if lo <= cp && cp <= hi {
            let pos = if cp == lo {
                0
            } else if cp == hi {
                2
            } else {
                1
            };
            return 0x1000_0000 + (i as u64) * 4 + pos;
        }
    }
    let (w, info) = tables::dbg_lookup(c);
    let flags = (tables::dbg_ligature_transparent(c) as u64)
        | (tables::dbg_transparent_zero_width(c) as u64) << 1
        | (tables::starts_emoji_presentation_seq(c) as u64) << 2
        | (tables::starts_non_ideographic_text_presentation_seq(c) as u64) << 3
        | (tables::is_emoji_modifier_base(c) as u64) << 4;
    0x2000_0000 + ((w as u64) << 24) + (((info != 0) as u64) << 8) + flags
}

fn keys(s: &str, set: &mut HashSet<(u16, u64, i8, u16)>) -> Vec<(u16, u64, i8, u16)> {
    let mut info = 0u16;
    let mut out = Vec::new();
    for c in s.chars().rev() {
        let (add, next) = tables::dbg_width_in_str(c, info);
        // Only transitions that differ from the context-free lookup are interesting once a
        // ligature state is active.
        let (plain_w, plain_info) = tables::dbg_lookup(c);
        let plain = if c as u32 <= 0xA0 { (1, if c == '\n' { 1 } else { 0 }) } else { (plain_w as i8, plain_info) };
        if info == 0 || (add, next) != plain {
            out.push((info, bucket(c), add, next));
        }
        info = next;
    }
    let _ = set;
    out
}

fn golden(count: usize, seed: u64) {
    let singles = singles();
    let atoms = atoms();
    let mut rng = Rng(seed);
    let mut seen: HashSet<(u16, u64, i8, u16)> = HashSet::new();
    let mut chosen: Vec<String> = Vec::new();
    let mut candidates: Vec<String> = Vec::new();
    // Hand-picked first: the atoms themselves, alone and wrapped.
    for a in atoms.iter() {
        candidates.push(a.clone());
    }
    for a in atoms.iter() {
        candidates.push(format!("a{a}"));
        candidates.push(format!("{a}b"));
        candidates.push(format!("世{a}界"));
    }
    for _ in 0..count {
        candidates.push(gen_string(&mut rng, &singles, &atoms));
    }
    // Shorter strings first, so each new transition is witnessed by a short string.
    let mut order: Vec<usize> = (0..candidates.len()).collect();
    order.sort_by_key(|&i| (candidates[i].chars().count(), i));
    let mut rest: Vec<String> = Vec::new();
    for &i in &order {
        let s = &candidates[i];
        let ks = keys(s, &mut seen);
        let mut new = false;
        for k in ks {
            if seen.insert(k) {
                new = true;
            }
        }
        if new {
            chosen.push(s.clone());
        } else {
            rest.push(s.clone());
        }
    }
    eprintln!("transition keys: {}, chosen {} strings", seen.len(), chosen.len());
    // Top up with random non-selected strings so plain sums and ordinary text are well represented.
    let mut extra = 0;
    while chosen.len() < 1800 && extra < rest.len() {
        let j = rng.below(rest.len() / 3); // `rest` is ordered by length: take short ones
        chosen.push(rest[j].clone());
        extra += 1;
    }
    chosen.sort();
    chosen.dedup();
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    for s in chosen {
        let w = s.width();
        assert_eq!(w, tables::str_width(&s));
        writeln!(out, "{w}\t{}", hex(&s)).unwrap();
    }
}

fn emoji(path: &str) {
    // The same selection as the crate's emoji_test_file test.
    let text = std::fs::read_to_string(path).unwrap();
    for line in text.lines() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (cps, status) = line.split_once(';').unwrap();
        let status = status.trim();
        if status.starts_with("fully-qualified") || status.starts_with("component") {
            let s: String = cps
                .trim()
                .split(' ')
                .map(|h| char::from_u32(u32::from_str_radix(h, 16).unwrap()).unwrap())
                .collect();
            println!("{}\t{}", s.width(), hex(&s));
        }
    }
}

// Every string of length lo..=hi over `alphabet` (each symbol is a string), preceded by `prefix`
// and followed by `suffix`.
fn exhaustive(out: &mut impl std::io::Write, alphabet: &[&str], lo: usize, hi: usize, prefix: &str, suffix: &str) {
    for len in lo..=hi {
        let total = (alphabet.len() as u64).pow(len as u32);
        for mut n in 0..total {
            let mut digits = vec![0usize; len];
            for d in digits.iter_mut().rev() {
                *d = (n % alphabet.len() as u64) as usize;
                n /= alphabet.len() as u64;
            }
            let mut s = String::from(prefix);
            for &i in &digits {
                s.push_str(alphabet[i]);
            }
            s.push_str(suffix);
            writeln!(out, "{}\t{}", s.width(), hex(&s)).unwrap();
        }
    }
}

fn matrix() {
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    // Tag sequences, every position and every boundary character just outside the ranges.
    let tags = ["a", "m", "z", "0", "9", "\u{E0060}", "\u{E007B}", "\u{E002F}", "\u{E003A}"];
    let tag = |c: &str| -> String {
        // ASCII 'a'.. 'z' and digits map onto the tag block
        match c.chars().next().unwrap() {
            ch @ ('a'..='z' | '0'..='9') => char::from_u32(0xE0000 + ch as u32).unwrap().to_string(),
            _ => c.to_string(),
        }
    };
    let tag_alphabet: Vec<String> = tags.iter().map(|t| tag(t)).collect();
    let tag_refs: Vec<&str> = tag_alphabet.iter().map(String::as_str).collect();
    exhaustive(&mut out, &tag_refs, 0, 4, "\u{1F3F4}", "\u{E007F}\u{200D}\u{1F600}");
    exhaustive(&mut out, &tag_refs[..2].iter().copied().chain([tag_refs[2], tag_refs[5], tag_refs[6]]).collect::<Vec<_>>(), 5, 7, "\u{1F3F4}", "\u{E007F}\u{200D}\u{1F600}");
    // The general alphabet of everything width_in_str has an arm for.
    let all: Vec<&str> = vec![
        "a", "#", "5", "\r", "\n", "\u{200D}", "\u{FE0F}", "\u{FE0E}", "\u{FE01}", "\u{FE00}",
        "\u{20E3}", "\u{301}", "\u{34F}", "\u{1F600}", "\u{2764}", "\u{231A}", "\u{1F44D}",
        "\u{1F3FB}", "\u{1F1E6}", "\u{1F1E7}", "\u{E007F}", "\u{E0067}", "\u{E0031}", "\u{644}",
        "\u{627}", "\u{5D0}", "\u{5DC}", "\u{17D2}", "\u{1780}", "\u{2D31}", "\u{2D7F}",
        "\u{1A15}", "\u{1A17}", "\u{1A10}", "\u{A4F8}", "\u{A4FC}", "\u{10C32}", "\u{10C03}",
        "\u{16D63}", "\u{16D67}", "\u{16D68}", "\u{16D69}", "\u{2018}", "\u{1F3F4}", "\u{1F201}",
        "\u{3000}",
    ];
    exhaustive(&mut out, &all, 1, 4, "", "");
    // Longer chains over smaller alphabets.
    exhaustive(&mut out, &["\u{1F1E6}", "\u{1F1E5}", "\u{1F200}", "\u{200D}", "a", "\u{FE0F}"], 1, 8, "", "");
    exhaustive(&mut out, &["\u{1F44D}", "\u{1F3FA}", "\u{1F3FB}", "\u{1F3FF}", "\u{1F400}", "\u{200D}", "\u{1F600}", "\u{FE0F}"], 1, 6, "", "");
    exhaustive(&mut out, &["#", "5", "*", "a", "\u{FE0F}", "\u{20E3}", "\u{200D}", "\u{1F600}"], 1, 6, "", "");
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    match args.get(1).map(String::as_str) {
        Some("dump") => dump(&args[2]),
        Some("fuzz") => fuzz(args[2].parse().unwrap(), args[3].parse().unwrap()),
        Some("golden") => golden(args[2].parse().unwrap(), args[3].parse().unwrap()),
        Some("emoji") => emoji(&args[2]),
        Some("matrix") => matrix(),
        _ => eprintln!("usage: wdump dump <dir> | fuzz <n> <seed> | golden <n> <seed> | emoji <file>"),
    }
}
